import{_ as s,l as i,o as e,c as l,v as t,p as c,x as o,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"RocksDB","description":"","frontmatter":{"title":"RocksDB","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rocksdb.md","filePath":"cs/rocksdb.md","lastUpdated":1789023840000}'),S={name:"cs/rocksdb.md"};function h(m,a,_,L,k,B){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="rocksdb" tabindex="-1">RocksDB <a class="header-anchor" href="#rocksdb" aria-label="Permalink to &quot;RocksDB&quot;">​</a></h1><div class="epigraph"><p>嵌入式 LSM：memtable、SST、compaction、WAL、列族。数据库用它当本地引擎，SQL 与分布式协议在它之上。</p><footer>—— 据 Facebook RocksDB；LevelDB；O&#39;Neil LSM 课的产品落地</footer></div><p>NewSQL 在<a href="/cs/newsql">上一课</a>收口。本课打开数据模型族：许多系统把节点内存储交给 RocksDB（或同类）。缺口不是再推导 leveled，而是<strong>嵌入式合同</strong>：无 SQL、无网络、调用者负责事务边界与线程。列族、事务、备份 API 如何接到前面的 WAL/MVCC。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RocksDB 提供 KV、可选事务（悲观锁或乐观）、快照、检查点、SST 摄入。缺口是调用者：MyRocks、TiKV、各种 NewSQL 本地。配置：compaction 风格、块缓存、写停顿——LSM 课的运维在此变成选项名。SQL 优化器看不见 SST，只看见「一次 Get/Iterator」的代价，校准要按 LSM 读放大。</p><p>列族：多套 LSM 共享 WAL，类似多表空间。与宽列不同，仍是 KV。</p><p><span class="marginnote">RocksDB 源自 LevelDB 加强。本课机制与嵌入边界。不把调参手册抄满。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写：Put 进 memtable+WAL。读：Get 走布隆+各层。扫描：Iterator 多路归并。事务：WriteBatch 或 TransactionDB。检查点：硬链 SST 给备份。与 CDC：WAL 可被上层抽，或上层另写。</p><p>线程：compaction 后台池与用户线程争 CPU/I/O，要限额，否则 OLTP 尾延迟。</p>',10)),(e(),c(p,null,{default:o(()=>[d(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20API%5B%22Get%20%2F%20Put%20%2F%20Iterator%22%5D%20--%3E%20MT%5B%22memtable%22%5D%0A%20%20API%20--%3E%20SST%5B%22%E5%A4%9A%E5%B1%82%20SST%22%5D%0A%20%20WAL%5B%22WAL%22%5D%20--%3E%20MT%0A%20%20CMP%5B%22compaction%20%E7%BA%BF%E7%A8%8B%22%5D%20--%3E%20SST%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与缓冲池：块缓存代替页池，替换策略仍抗扫描。pin 变成 iterator 钉块。无 B+ latch crabbing，有文件引用计数。TDE 可在文件层。</p><p>版本：快照序列号，GC 与 compaction 水位——MVCC GC 课的 LSM 实例。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲文档模型。也不把 RocksDB 当事务管理器的全部（分布式仍在上层）。图/时序常在上面再编码。</p><p>后课默认：见到「用 RocksDB」就用 LSM 放大与写停顿读它。文档数据库：嵌套文档与二级索引，常仍 LSM 底下。</p><p>嵌入式引擎把 SQL 优化器的「表」变成 KV 的编码约定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RocksDB 是嵌入式 LSM：WAL、SST、列族、本地事务。</li><li>上层负责 SQL 与分片；调参即 LSM 合同。</li><li>文档数据库下一课。</li><li>出处：RocksDB/LevelDB；O&#39;Neil LSM。</li></ul>',9))])}const A=s(S,[["render",h]]);export{D as __pageData,A as default};
